"use client"

import * as React from "react"
import {
  AudioLinesIcon,
  MicIcon,
  PaperclipIcon,
  PlusIcon,
  SearchIcon,
  SendIcon,
  SparklesIcon,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"

const press =
  "rounded-full transition-[scale,background-color] duration-150 ease-out active:scale-[0.96] motion-reduce:active:scale-100"

export default function ChatComposer01() {
  const [message, setMessage] = React.useState("")
  const [isExpanded, setIsExpanded] = React.useState(false)
  const [listening, setListening] = React.useState(false)
  const textareaRef = React.useRef<HTMLTextAreaElement>(null)
  const fileInputRef = React.useRef<HTMLInputElement>(null)

  const resize = () => {
    const el = textareaRef.current
    if (!el) return
    el.style.height = "auto"
    el.style.height = `${el.scrollHeight}px`
  }

  const send = () => {
    if (!message.trim()) return
    setMessage("")
    setIsExpanded(false)
    setListening(false)
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto"
    }
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    send()
  }

  const handleTextareaChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value
    setMessage(value)
    resize()
    setIsExpanded(value.length > 100 || value.includes("\n"))
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault()
      send()
    }
  }

  const attachMenu = (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          type="button"
          aria-label="Add attachments"
          className={press}
          size="icon-lg"
          variant="ghost"
        >
          <PlusIcon className="size-5 text-muted-foreground" aria-hidden />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="start"
        className="w-64 rounded-[16px] p-1.5"
      >
        <DropdownMenuGroup className="space-y-1">
          <DropdownMenuItem
            className="gap-2.5 rounded-[10px] px-2.5 py-2"
            onSelect={() => fileInputRef.current?.click()}
          >
            <PaperclipIcon className="size-5 opacity-60" aria-hidden />
            Add photos & files
          </DropdownMenuItem>
          <DropdownMenuItem className="gap-2.5 rounded-[10px] px-2.5 py-2">
            <SparklesIcon className="size-5 opacity-60" aria-hidden />
            Agent mode
          </DropdownMenuItem>
          <DropdownMenuItem className="gap-2.5 rounded-[10px] px-2.5 py-2">
            <SearchIcon className="size-5 opacity-60" aria-hidden />
            Deep Research
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )

  return (
    <div className="w-full bg-canvas px-4 py-16 text-foreground sm:px-6">
      <h1 className="mx-auto mb-6 max-w-2xl text-balance text-center text-3xl font-semibold leading-tight tracking-tight">
        How can I help you today?
      </h1>

      <form className="group/composer w-full" onSubmit={handleSubmit}>
        <input
          className="sr-only"
          multiple
          ref={fileInputRef}
          type="file"
          tabIndex={-1}
          aria-hidden
        />

        <div
          className={cn(
            "mx-auto w-full max-w-2xl cursor-text overflow-clip bg-background bg-clip-padding p-2.5 shadow-[0_0_0_1px_oklch(0_0_0/0.08),0_1px_2px_-1px_oklch(0_0_0/0.08),0_4px_12px_-2px_oklch(0_0_0/0.08)] dark:bg-muted/50 dark:shadow-[0_0_0_1px_oklch(1_0_0/0.1)]",
            isExpanded
              ? "grid rounded-[28px] [grid-template-areas:'header'_'primary'_'footer'] [grid-template-columns:1fr] [grid-template-rows:auto_1fr_auto]"
              : "grid rounded-full [grid-template-areas:'header_header_header'_'leading_primary_trailing'_'._footer_.'] [grid-template-columns:auto_1fr_auto] [grid-template-rows:auto_1fr_auto]"
          )}
          onClick={() => textareaRef.current?.focus()}
        >
          <div
            className={cn(
              "flex overflow-x-hidden",
              isExpanded
                ? "px-2 pt-1.5 pb-2"
                : "-my-2.5 min-h-14 items-center px-1.5"
            )}
            style={{ gridArea: "primary" }}
          >
            <div className="max-h-52 flex-1 overflow-auto">
              <Textarea
                ref={textareaRef}
                className="min-h-0 resize-none rounded-none border-0 bg-transparent p-0 text-base shadow-none placeholder:text-muted-foreground focus-visible:ring-0 md:text-base dark:bg-transparent"
                onChange={handleTextareaChange}
                onKeyDown={handleKeyDown}
                onClick={(e) => e.stopPropagation()}
                placeholder={listening ? "Listening..." : "Ask anything"}
                aria-label="Ask anything"
                rows={1}
                value={message}
              />
            </div>
          </div>

          <div
            className={cn("flex items-center", isExpanded && "hidden")}
            style={{ gridArea: "leading" }}
            onClick={(e) => e.stopPropagation()}
          >
            {attachMenu}
          </div>

          <div
            className="flex items-center gap-2"
            style={{ gridArea: isExpanded ? "footer" : "trailing" }}
            onClick={(e) => e.stopPropagation()}
          >
            {isExpanded ? attachMenu : null}
            <div className="ms-auto flex items-center gap-1.5">
              <Button
                type="button"
                aria-label={
                  listening ? "Stop voice input" : "Record audio message"
                }
                aria-pressed={listening}
                className={cn(
                  press,
                  listening &&
                    "bg-destructive/15 text-destructive hover:bg-destructive/20 hover:text-destructive"
                )}
                size="icon-lg"
                variant="ghost"
                onClick={() => setListening((v) => !v)}
              >
                <MicIcon
                  className={cn(
                    "size-5",
                    listening
                      ? "animate-pulse text-destructive"
                      : "text-muted-foreground"
                  )}
                  aria-hidden
                />
              </Button>

              <Button
                type="button"
                aria-label="Audio visualization"
                className={press}
                size="icon-lg"
                variant="ghost"
              >
                <AudioLinesIcon
                  className="size-5 text-muted-foreground"
                  aria-hidden
                />
              </Button>

              <Button
                type="submit"
                aria-label="Send message"
                className={cn(
                  press,
                  "transition-[scale,opacity,background-color] disabled:opacity-40"
                )}
                disabled={!message.trim()}
                size="icon-lg"
              >
                <SendIcon className="size-4.5 icon-dir" aria-hidden />
              </Button>
            </div>
          </div>
        </div>
      </form>
    </div>
  )
}
